/**
 * The 64 districts of Bangladesh as SVG paths, for the National TV Wall's
 * map. Generated from geoBoundaries gbOpen BGD ADM2 (CC0 1.0) in the same
 * projection as data/bangladesh-map.ts, so the division outlines there sit
 * exactly on these, then simplified (Douglas–Peucker, 0.7px). Regenerate
 * rather than hand-edit: the paths are data, not art.
 */
import type { DivisionId } from "../bangladesh-map.ts";

export interface DistrictShape {
  id: string;
  en: string;
  bn: string;
  division: DivisionId;
  /** Older or alternative English spellings news still uses. */
  alias: string[];
  /** Label point (centroid of the largest part), in map units. */
  cx: number;
  cy: number;
  d: string;
}

export const DISTRICT_MAP_SOURCE = {
  name: "geoBoundaries — Bangladesh ADM2 (District)",
  license: "CC0 1.0",
  url: "https://www.geoboundaries.org/countryDownloads.html",
};

